182: function applyEffects(state, effect = {}) {
183:   Object.entries(effect).forEach(([key, value]) => {
184:     if (!Object.prototype.hasOwnProperty.call(state, key)) return;
185:     state[key] += value;
186:   });
187: 
188:   state.crew = clamp(state.crew, 0, 99);
189:   state.morale = clamp(state.morale, 0, 100);
190:   state.supplies = clamp(state.supplies, 0, 100);
191:   state.shields = clamp(state.shields, 0, 100);
192:   state.scrap = clamp(state.scrap, 0, 999);
193:   state.reputation = clamp(state.reputation, -20, 20);
194: }
