238: function createStats(state) {
239:   const stats = [
240:     { label: 'Crew', value: state.crew },
241:     { label: 'Morale', value: `${state.morale}%` },
242:     { label: 'Supplies', value: `${state.supplies}%` },
243:     { label: 'Shields', value: `${state.shields}%` },
244:     { label: 'Scrap', value: state.scrap },
245:     { label: 'Rep', value: `${state.reputation}` }
246:   ];
