271: function getEndingTone(state) {
272:   const score = state.reputation + Math.floor(state.morale / 10) + Math.floor(state.supplies / 10) - Math.floor(state.crew / 10);
273:   if (score >= 14) return { tone: 'good', message: 'The frontier accepts your leadership and the sector begins to thrive.' };
274:   if (score <= 3) return { tone: 'danger', message: 'Your choices leave the sector fractured, bitter, and unable to trust the next generation.' };
275:   return { tone: 'warn', message: 'A mixed legacy: the route is open, but the cost remains heavy and the future is uncertain.' };
276: }
