278: function renderShop(state) {
279:   const sceneEl = document.getElementById('scene');
280:   const cards = shopItems.map((item) => {
281:     const owned = state.inventory.includes(item.id);
282:     const equipped = (item.kind === 'weapon' && state.weapon === item.name)
283:       || (item.kind === 'armor' && state.armor === item.name);
284:     const status = equipped ? 'Equipped' : owned ? 'Owned' : `${item.price} scrap`;
285:     const disabled = (owned && item.kind !== 'supply' && item.kind !== 'medkit') || state.scrap < item.price;
286:     const buttonText = equipped ? 'Equipped' : owned ? 'Already owned' : state.scrap < item.price ? 'Not enough scrap' : 'Purchase';
287:     return `<article class="shop-item">
288:       <div class="shop-item-head"><span class="choice-tag">${item.kind}</span><span class="shop-cost">${status}</span></div>
289:       <h3>${item.name}</h3><p>${item.detail}</p>
290:       <button class="choice-btn shop-buy" data-item="${item.id}" type="button" ${disabled ? 'disabled' : ''}><strong>${buttonText}</strong></button>
291:     </article>`;
292:   }).join('');
293: 
294:   sceneEl.innerHTML = `<div class="scene-top"><h2>Shipyard & Supply Deck</h2><span class="scene-badge">${state.scrap} scrap available</span></div>
295:     <div class="scene-body shop-layout"><div class="story-copy">
296:       <p>Upgrade the Arbiter before you commit to the Verge. Bought weapons and suits stay in your inventory; equipping a new one is free. Consumables take effect immediately.</p>
297:       <div class="shop-grid">${cards}</div>
298:     </div><aside class="side-panel">
299:       <div class="mission-box"><h3>Loadout</h3><p><strong>Weapon:</strong> ${state.weapon} (+${state.weaponBonus})<br><strong>Suit:</strong> ${state.armor} (+${state.armorBonus})</p></div>
300:       <div class="mission-box"><h3>Free expansions</h3><p>The Quiet Signal bonus episode is included at no cost. Open it any time from the top bar.</p></div>
301:       <button id="returnFromShop" class="ghost-btn" type="button">Return to voyage</button>
302:     </aside></div>`;
303: 
304:   sceneEl.querySelectorAll('.shop-buy').forEach((button) => {
305:     button.addEventListener('click', () => {
306:       const item = shopItems.find((entry) => entry.id === button.dataset.item);
307:       if (!item || state.scrap < item.price) return;
308:       if (item.kind !== 'supply' && item.kind !== 'medkit' && state.inventory.includes(item.id)) return;
309:       state.scrap -= item.price;
310:       if (item.kind === 'weapon') {
311:         state.inventory.push(item.id);
312:         state.weapon = item.name;
313:         state.weaponBonus = item.bonus;
314:         state.log.push(`Purchased and equipped ${item.name}.`);
315:       } else if (item.kind === 'armor') {
316:         state.inventory.push(item.id);
317:         state.armor = item.name;
318:         state.armorBonus = item.bonus;
319:         state.log.push(`Purchased and equipped ${item.name}.`);
320:       } else if (item.kind === 'supply') {
321:         state.supplies = clamp(state.supplies + 22, 0, 100);
322:         state.log.push('Field rations restored 22 supplies.');
323:       } else {
324:         state.crew = clamp(state.crew + 2, 0, 99);
325:         state.log.push('A crew medkit restored two crew.');
326:       }
327:       renderGame(state);
328:     });
329:   });
330:   document.getElementById('returnFromShop').addEventListener('click', () => {
331:     state.screen = 'story';
332:     renderGame(state);
333:   });
334: }
