336: function renderCombat(state, scene) {
337:   const sceneEl = document.getElementById('scene');
338:   const result = state.combatResult;
339:   const actionLabels = { attack: 'Fire weapon', maneuver: 'Evasive maneuver', negotiate: 'Open a channel' };
340:   const actionInfo = {
341:     attack: `Attack bonus: +${state.weaponBonus} weapon + ${Math.floor(state.morale / 25)} morale`,
342:     maneuver: `Maneuver bonus: +${state.armorBonus} suit + 2 pilot training`,
343:     negotiate: `Diplomacy bonus: +${Math.floor(state.reputation / 2)} reputation + ${Math.floor(state.morale / 20)} morale`
344:   };
345:   sceneEl.innerHTML = `<div class="scene-top"><h2>${scene.title}</h2><span class="scene-badge">${scene.badge}</span></div>
346:     <div class="scene-body combat-layout"><div class="story-copy">
347:       <p>${scene.text}</p>
348:       <div class="combat-console">
349:         <div class="enemy-card"><span class="eyebrow">Hostile contact · threat 14</span><strong>Verge Raider Skiff</strong><p>Hull 1 · Disruptor lock active</p></div>
350:         ${result ? `<div class="roll-result ${result.success ? 'good' : 'danger'}"><span class="die-face">${result.roll}</span><div><strong>${result.headline}</strong><p>d20 ${result.roll} + ${result.bonus} = ${result.total} vs DC ${result.dc}. ${result.message}</p></div></div>
351:           <button id="continueCombat" class="choice-btn" type="button"><strong>Continue to the Verge</strong></button>` : `<div class="action-list" role="group" aria-label="Combat approach">
352:           ${Object.entries(actionLabels).map(([key, label]) => `<button class="action-btn ${state.combatAction === key ? 'selected' : ''}" data-action="${key}" type="button"><strong>${label}</strong><span>${actionInfo[key]}</span></button>`).join('')}
353:         </div><button id="rollCombat" class="roll-btn" type="button">🎲 Roll d20 — ${actionLabels[state.combatAction]}</button><p class="dice-note">Natural 20: critical success · Natural 1: critical failure</p>`}
354:       </div>
355:     </div><aside class="side-panel"><div class="mission-box"><h3>Equipped</h3><p><strong>${state.weapon}</strong><br>Weapon bonus +${state.weaponBonus}<br><br><strong>${state.armor}</strong><br>Maneuver bonus +${state.armorBonus}</p></div><div class="outcome-box warn"><h3>Check</h3><p>Roll a d20 and add the bonus for your chosen approach. Meet or beat the DC to turn the ambush in your favor.</p></div></aside></div>`;
356: 
357:   if (result) {
358:     document.getElementById('continueCombat').addEventListener('click', () => {
359:       state.currentKey = 'intro';
360:       state.chapter = 'Departure';
361:       state.combatResult = null;
362:       renderGame(state);
363:     });
364:     return;
365:   }
366:   sceneEl.querySelectorAll('.action-btn').forEach((button) => {
367:     button.addEventListener('click', () => {
368:       state.combatAction = button.dataset.action;
369:       renderGame(state);
370:     });
371:   });
372:   document.getElementById('rollCombat').addEventListener('click', () => {
373:     const roll = Math.floor(Math.random() * 20) + 1;
374:     const bonuses = {
375:       attack: state.weaponBonus + Math.floor(state.morale / 25),
376:       maneuver: state.armorBonus + 2,
377:       negotiate: Math.floor(state.reputation / 2) + Math.floor(state.morale / 20)
378:     };
379:     const dc = state.combatAction === 'maneuver' ? 15 : state.combatAction === 'negotiate' ? 13 : 14;
380:     const bonus = bonuses[state.combatAction];
381:     const total = roll + bonus;
382:     const success = roll === 20 || (roll !== 1 && total >= dc);
383:     let headline;
